      "status": "explicit",
      "alters_key_if_changed": true,
      "convention_evidence_ids": []
    },
    {
      "condition": "The second receipt does not reduce the government’s financial assets.",
      "status": "missing",
      "alters_key_if_changed": true,
      "convention_evidence_ids": []
    },
    {
      "condition": "“Non-tax receipt” means non-tax revenue rather than any receipt that is not a tax.",
      "status": "implied_decisive",
      "alters_key_if_changed": true,
      "convention_evidence_ids": []
    },
    {
