      "status": "convention",
      "alters_key_if_changed": true,
      "convention_evidence_ids": [
        "E1.1"
      ]
    },
    {
      "condition": "Capital receipts include receipts that create a liability or reduce financial assets.",
      "status": "convention",
      "alters_key_if_changed": true,
      "convention_evidence_ids": [
        "E3.2"
      ]
    }
  ],
  "option_challenges": [
    {
      "option": "B",
      "strongest_reading": "If the second receipt is proceeds from selling a government asset, financial assets fall and it is capital; the tax receipt remains revenue.",
      "correct_under_reading": true,
      "reading_status": "reasonable_unstated",
      "convention_evidence_ids": []
    },
    {
      "option": "C",
      "strongest_reading": "No fair reading reverses the excerpt’s classification of tax revenues as revenue receipts; the option’s tax-as-capital clause fails.",
      "correct_under_reading": false,
      "reading_status": "strained",
      "convention_evidence_ids": []
    },
    {
      "option": "D",
      "strongest_reading": "One could try to treat absence of a claim as irrelevant, but the supplied definition says receipts without a claim are revenue receipts.",
      "correct_under_reading": false,
      "reading_status": "strained",
      "convention_evidence_ids": []
    }
  ],
  "blocking_defects": [
    {
      "category": "missing_decisive_assumption",
      "detail": "The stem does not say whether the non-tax receipt reduces financial assets. If it does, it can be a capital receipt; if it does not and is non-tax revenue, it is a revenue receipt."
    }
  ],
  "style_notes": [
    "“Non-tax receipt” is less precise than “non-tax revenue” if the intended category is revenue."
  ],
